 "content": "def transform(grid):
    """Fill the interiors of rectangular 2-colored frames with 8, preserving 2s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    boxes = []
    # Find every axis-aligned rectangle whose complete perimeter is color 2.
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    if (all(grid[r0][c] == 2 and grid[r1][c] == 2 for c in range(c0, c1 + 1))
                        and all(grid[r][c0] == 2 and grid[r][c1] == 2 for r in range(r0, r1 + 1))):
                        boxes.append((r0, r1, c0, c1))
    # Recolor only zero cells strictly inside each frame.
    for r0, r1, c0, c1 in boxes:
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if out[r][c] == 0:
                    out[r][c] = 8
    return out
